using System;using System.IO;using System.Linq;using System.Text;using System.Text.RegularExpressions;using System.Collections.Generic;using System.Web.Script.Serialization;
public static class EvidenceBindings {
 static Dictionary<string,object>D(object o){return ManualHypotheses.D(o);}static object V(Dictionary<string,object>d,string k){return ManualHypotheses.V(d,k);}static string S(Dictionary<string,object>d,string k){return ManualHypotheses.S(d,k);}static IEnumerable<Dictionary<string,object>>Items(Dictionary<string,object>d,string k){return ManualHypotheses.A(V(d,k)).Select(D);}static Dictionary<string,object>Parse(string s){return LocalJson.ParseObject(s);}
 static Dictionary<string,object>Read(string root,string name,out string hash){if(!Regex.IsMatch(name,@"^(analysis-inputs/[0-9a-f]{64}\.json|observation-snapshots/[0-9a-f]{64}\.json|attribution-cases/[a-z0-9][a-z0-9-]{0,63}-catalog\.json|research-candidate-reviews\.json)$"))throw new InvalidDataException("Unexpected evidence container path");string path=Path.Combine(root,name);if(new FileInfo(path).Length>8388608)throw new InvalidDataException("Evidence container too large");byte[]raw=File.ReadAllBytes(path);using(var h=System.Security.Cryptography.SHA256.Create())hash=BitConverter.ToString(h.ComputeHash(raw)).Replace("-","").ToLowerInvariant();return Parse(LocalJson.Decode(raw));}
 public static Dictionary<string,object>Capture(string root,Dictionary<string,object>material){var copy=Parse(ManualHypotheses.Serialize(material));Check(root,copy,true);return copy;}
 public static void Check(string root,Dictionary<string,object>material,bool capture){string text=S(material,"text"),kind=S(material,"kind");if(text==""||ProvenanceAudit.Sha(text)!=S(material,"text_sha256"))throw new InvalidDataException("Source snapshot text hash mismatch");bool bound=false;var authors=new HashSet<string>();foreach(var o in Items(material,"origins")){string name=S(o,"container"),hash;var data=Read(root,name,out hash);if(S(o,"container_sha256")!=""&&S(o,"container_sha256")!=hash)throw new InvalidDataException("Historical source container bytes changed");string field=S(o,"source_field");Dictionary<string,object>row;string actual,expectedUrl,expectedKind,expectedCaptured;if(name.StartsWith("attribution-cases/",StringComparison.Ordinal)){var sourceEntry=D(V(D(V(data,"sources")),S(o,"evidence_id")));row=D(V(D(V(sourceEntry,"fields")),field));actual=row.ContainsKey("text")?S(row,"text"):S(row,"full_text");if(S(row,"reported_author_id")!=S(o,"reported_author_id"))throw new InvalidDataException("Diagnostic author metadata changed");expectedUrl=S(row,"url")==""?S(sourceEntry,"url"):S(row,"url");expectedKind=field=="answer_text"?"community_answer":"archived_original";expectedCaptured=S(row,"captured_at")==""?S(sourceEntry,"observed_at"):S(row,"captured_at");}else{if(field!="context_text"&&field!="answer_text"&&field!="title")throw new InvalidDataException("Unexpected source field");var matches=Items(data,"observations").Where(r=>S(r,"evidence_id")==S(o,"evidence_id")&&S(r,"observation_id")==S(o,"observation_id")).ToArray();if(matches.Length!=1)throw new InvalidDataException("Ambiguous saved source origin");row=matches[0];actual=S(row,field);if(S(row,field=="answer_text"?"answer_author_id":"author_id")!=S(o,"reported_author_id"))throw new InvalidDataException("Saved author metadata changed");expectedUrl=field=="answer_text"&&S(row,"answer_url")!=""?S(row,"answer_url"):S(row,"url");expectedCaptured=field=="answer_text"?S(row,"answer_observed_at"):field=="context_text"&&S(row,"context_observed_at")!=""?S(row,"context_observed_at"):S(row,"observed_at");expectedKind=field=="answer_text"?"community_answer":S(row,"kind")=="package_listing_not_demand"?"package_listing":field=="title"?"metadata_only":new[]{"question_body","original_post_only","original_ask_post"}.Contains(S(row,"content_scope"))?"archived_original":"unscoped_observation";}if(actual!=text)throw new InvalidDataException("Exact saved source field differs from draft snapshot");if(S(material,"url")!=expectedUrl||S(o,"url")!=expectedUrl||S(material,"captured_at")!=expectedCaptured||S(o,"captured_at")!=expectedCaptured||kind!=expectedKind)throw new InvalidDataException("Source URL, date or role binding mismatch");authors.Add(S(o,"reported_author_id")==""?"unknown":S(o,"reported_author_id"));if(capture)o["container_sha256"]=hash;bound=true;}
 if(authors.Count>0&&S(material,"author")!=(authors.Count==1?authors.Single():"differing saved author metadata; see exact origins; identity not inferred"))throw new InvalidDataException("Source author display differs from saved metadata");
 if(kind=="original_post"||kind=="provider_document"){string hash;var state=Read(root,"research-candidate-reviews.json",out hash);var wanted=ManualHypotheses.A(V(material,"version_ids")).Select(Convert.ToString).ToArray();if(wanted.Length==0)throw new InvalidDataException("Public source has no immutable version binding");foreach(string versionId in wanted){bool found=false;foreach(var item in D(V(state,"items")).Values)foreach(var wrap in Items(D(item),"research_versions")){string payload=S(wrap,"payload_json");if(S(wrap,"payload_sha256")!=versionId)continue;if(ProvenanceAudit.Sha(payload)!=versionId)throw new InvalidDataException("Public research version hash mismatch");var version=Parse(payload);foreach(var row in Items(version,kind=="original_post"?"sources":"documents"))if(S(row,"url")==S(material,"url")&&S(row,"text")==text&&S(row,"text_sha256")==S(material,"text_sha256")&&S(row,"captured_at")==S(material,"captured_at")&&S(row,"author")==S(material,"author"))found=true;}if(!found)throw new InvalidDataException("Exact public source revision missing");}bound=true;}
 if(!bound)throw new InvalidDataException("No exact saved source origin; manual draft not stored");}
}
